import React, {type ReactNode, useContext} from 'react';
import {addLeadingSlash} from '@docusaurus/utils-common';
import {ReactContextError} from '@docusaurus/theme-common/internal';
import type {PropVersionMetadata} from '@docusaurus/plugin-content-docs';
import type {GlobalVersion} from '@docusaurus/plugin-content-docs/client';

const Context = React.createContext<PropVersionMetadata | null>(null);

/**
 * Provide the current version's metadata to your children.
 */
export function DocsVersionProvider({
  children,
  version,
}: {
  children: ReactNode;
  version: PropVersionMetadata | null;
}): JSX.Element {
  return <Context.Provider value={version}>{children}</Context.Provider>;
}

/**
 * Gets the version metadata of the current doc page.
 */
export function useDocsVersion(): PropVersionMetadata {
  const version = useContext(Context);
  if (version === null) {
    throw new ReactContextError('DocsVersionProvider');
  }
  return version;
}

export class DocsVersionRecord {
  private readonly name: string;
  private readonly label: string;
  private readonly isLast: boolean;
  private readonly path: string;
  private readonly mainDocId: string;
  private readonly source: GlobalVersion;

  constructor(version: GlobalVersion) {
    this.name = version.name;
    this.label = version.label;
    this.isLast = version.isLast;
    this.path = version.path;
    this.mainDocId = version.mainDocId;
    this.source = version;
  }

  getName(): string {
    return this.name;
  }

  getLabel(): string {
    return this.label;
  }

  isLastVersion(): boolean {
    return this.isLast;
  }

  getPath(): string {
    return this.path ? addLeadingSlash(this.path) : this.path;
  }

  getMainDocId(): string {
    return this.mainDocId;
  }

  getSource(): GlobalVersion {
    return this.source;
  }
}

