input.oldString:
class ActiveVersionLocator {
  constructor(
    private readonly pathname: string,
    private readonly records: DocsVersionRecord[],
  ) {}

  getActiveVersion(): GlobalVersion | undefined {
    // Version paths are prefixes of each other (e.g. /docs and /docs/next).
    // We need to match the most specific path first, otherwise a version whose
    // path is a prefix of another version's path would always win.
    // This also handles the docs-only case where the current version path is
    // "/" and would otherwise match every pathname.
    const orderedRecords = [...this.records].sort(
      (a, b) => b.getPath().length - a.getPath().length,
    );
    return orderedRecords.find(
      (record) =>
        !!matchPath(this.pathname, {
          path: record.getPath(),
          exact: false,
          strict: false,
        }),
    )?.getSource();
  }
}

export function getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  const records = data.versions.map(
    (version) => new DocsVersionRecord(version),
  );
  return new ActiveVersionLocator(pathname, records).getActiveVersion();
}

