export const getLatestVersion = (data: GlobalPluginData): GlobalVersion =>
  data.versions.find((version) => version.isLast)!;

export function getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  // Version paths are prefixes of each other (e.g. /docs and /docs/next).
  // We need to match the most specific path first, otherwise a version whose
  // path is a prefix of another version's path would always win.
  // This also handles the docs-only case where the current version path is
  // "/" and would otherwise match every pathname.
  return [...data.versions]
    .sort((a, b) => b.path.length - a.path.length)
    .find((version) =>
      matchPath(pathname, {
        path: version.path,
        exact: false,
        strict: false,
      }),
    );
}

export function getActiveDocContext(
  data: GlobalPluginData,
  pathname: string,
): ActiveDocContext {
  const activeVersion = getActiveVersion(data, pathname);
  const activeDoc = activeVersion?.docs.find(
    (doc) =>
      !!matchPath(pathname, {
        path: doc.path,
        exact: true,
        strict: false,
      }),
  );

